# DK VFN.  Vanløse – Frederiksberg Nord
#
let vn = path("d3.dk.vfn");

with detail = 4, railway = :first :nopax :removed {
    with link = "line.dk.VFN" {
        track(:dn:rup, vn[:van + 0.5sw, :van.yn] << 1.5mo);

        with layer = -2 track(:up:ldn:rup,
                vn[:van.yn - 0.1dl, :van.yn] << 0.5mo
            ..  vn[:frn.yv, :frn.yv + 0.1dl] << 1.5mo
        );
        track(:up:ldn:ror,
                vn[:van.yn - 0.1dl, :van.yn] << 1.5mo
            ..  vn[:frn.yv, :frn.yv + 0.1dl] << 2.5mo
        );

        track(:double:ror, vn[:frn.yv, :cfr - 0.49sw] << 2mo);
        track(:double:ror, vn[:cfr - 0.5sw, :cfr + 0.5sw] << 2mo);
        track(:double:ror, vn[:cfr + 0.49sw, :frn - 3.9dl] << 2mo);
    }
}

